import{J as e,K as t,U as n,Y as r,dt as i,n as a,q as o,st as s}from"./chunks/framework.Bzm6Ex2A.js";var c=JSON.parse(`{"title":"Contribute","description":"How to contribute to the Citizen skin.","frontmatter":{"title":"Contribute","description":"How to contribute to the Citizen skin."},"headers":[],"relativePath":"contribute/index.md","filePath":"contribute/index.md","lastUpdated":1789857802000}`),l={name:`contribute/index.md`};function u(a,c,l,u,d,f){let p=i(`CopyOrDownloadAsMarkdownButtons`);return s(),t(`div`,null,[c[0]||=n(`h1`,{id:`contributing`,tabindex:`-1`},[e(`Contributing `),n(`a`,{class:`header-anchor`,href:`#contributing`,"aria-label":`Permalink to “Contributing”`},`​`)],-1),r(p),c[1]||=o(`<p>Thank you for considering contributing to <em>Citizen</em>!</p><p><em>Citizen</em> is a small open-source project, and we appreciate any help. Here are some ways you can contribute:</p><ul><li><a href="https://github.com/StarCitizenTools/mediawiki-skins-Citizen/pulls" target="_blank" rel="noreferrer">Code patches</a></li><li><a href="https://mwcitizen.skin/" target="_blank" rel="noreferrer">Documentation improvements</a></li><li><a href="https://github.com/StarCitizenTools/mediawiki-skins-Citizen/issues/new?template=bug_report.yml" target="_blank" rel="noreferrer">Bug reports</a></li><li><a href="https://github.com/StarCitizenTools/mediawiki-skins-Citizen/issues/new?template=feature_request.yml" target="_blank" rel="noreferrer">Feature requests and suggestions</a></li><li><a href="#translations">Translations</a></li></ul><h2 id="how-to-submit-a-contribution" tabindex="-1">How to submit a contribution <a class="header-anchor" href="#how-to-submit-a-contribution" aria-label="Permalink to “How to submit a contribution”">​</a></h2><ol><li><a href="https://github.com/StarCitizenTools/mediawiki-skins-Citizen/fork" target="_blank" rel="noreferrer">Fork</a> the <em>Citizen</em> repository.</li><li>Create a new branch in your fork to make your changes.</li><li>Commit your changes to your new branch.</li><li>Push your changes to your fork on GitHub.</li><li>Submit a pull request from your branch to the <em>Citizen</em> repository.</li></ol><p>We will review your pull request and, if everything looks good, merge it into the main codebase.</p><h2 id="ai-assisted-contributions" tabindex="-1">AI-assisted contributions <a class="header-anchor" href="#ai-assisted-contributions" aria-label="Permalink to “AI-assisted contributions”">​</a></h2><p>The maintainers of <em>Citizen</em> use AI tools (such as LLMs and code assistants) as part of their development workflow. Contributors are welcome to do the same, subject to the following expectations:</p><h3 id="human-accountability" tabindex="-1">Human accountability <a class="header-anchor" href="#human-accountability" aria-label="Permalink to “Human accountability”">​</a></h3><p>The person submitting a contribution is fully responsible for it, regardless of how it was produced. If you use AI to help write code, you must understand what the code does, verify that it works, and be prepared to maintain it.</p><h3 id="licensing-and-copyright" tabindex="-1">Licensing and copyright <a class="header-anchor" href="#licensing-and-copyright" aria-label="Permalink to “Licensing and copyright”">​</a></h3><p>You must ensure that your contribution is compatible with the project&#39;s license (<a href="https://github.com/StarCitizenTools/mediawiki-skins-Citizen/blob/main/LICENSE" target="_blank" rel="noreferrer">GPL-3.0-or-later</a>) and does not incorporate third-party code in a way that violates its copyright or license terms. This applies to all contributions — whether written by hand, copied from a reference, or generated with a tool.</p><h3 id="quality-over-volume" tabindex="-1">Quality over volume <a class="header-anchor" href="#quality-over-volume" aria-label="Permalink to “Quality over volume”">​</a></h3><p>Every submission should be purposeful, well-tested, and reviewed for correctness, style, and fit with the project. PRs that appear to be unreviewed AI output — large dumps of generated code, generic boilerplate, or changes that ignore the project&#39;s conventions — will be closed.</p><h3 id="communication" tabindex="-1">Communication <a class="header-anchor" href="#communication" aria-label="Permalink to “Communication”">​</a></h3><p>Commit messages, PR descriptions, and review comments should be clear, specific, and relevant — regardless of how they were drafted. Generic filler like &quot;This PR improves code quality and enhances maintainability&quot; tells reviewers nothing. Make sure your communication actually describes what changed and why.</p><h2 id="translations" tabindex="-1">Translations <a class="header-anchor" href="#translations" aria-label="Permalink to “Translations”">​</a></h2><p>You can submit translations via <a href="https://translatewiki.net/w/i.php?title=Special:Translate&amp;group=mwgithub-star-citizen" target="_blank" rel="noreferrer">TranslateWiki.net</a>. They are usually merged bi-weekly.</p><h2 id="questions" tabindex="-1">Questions <a class="header-anchor" href="#questions" aria-label="Permalink to “Questions”">​</a></h2><p>If you have any questions about contributing, feel free to <a href="https://github.com/StarCitizenTools/mediawiki-skins-Citizen/issues/new/choose" target="_blank" rel="noreferrer">open an issue</a> and ask.</p><h2 id="documentation-previews" tabindex="-1">Documentation previews <a class="header-anchor" href="#documentation-previews" aria-label="Permalink to “Documentation previews”">​</a></h2><p>Every pull request that changes the documentation gets its own live preview site — a bot comments on the PR with the link shortly after you push, and the preview updates on every subsequent push. No local setup needed to see your changes rendered.</p><p>Previews are built for branches in the main repository. Pull requests from forks still run the documentation lint and build checks, but don&#39;t get a preview link.</p><h2 id="adding-a-wiki-to-the-showcase" tabindex="-1">Adding a wiki to the showcase <a class="header-anchor" href="#adding-a-wiki-to-the-showcase" aria-label="Permalink to “Adding a wiki to the showcase”">​</a></h2><p>The <a href="./../community/showcase">showcase</a> is built from <code>docs/data/showcase.json</code>. Wiki owners can ask to be listed with the <a href="https://github.com/StarCitizenTools/mediawiki-skins-Citizen/issues/new?template=showcase_submission.yml" target="_blank" rel="noreferrer">submission form</a>; adding an entry by hand is one line — the wiki&#39;s name, its URL and one tag from <code>games</code>, <code>media</code>, <code>technology</code> or <code>real-world</code>:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Star Citizen Wiki&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://starcitizen.tools&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;tags&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;games&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span></code></pre></div><p>An unknown tag fails the build on purpose: a handful of broad topics is what makes the filter worth using, and a vocabulary that grows with every submission would sort nothing.</p><p>Everything else fills in by itself. A weekly job refreshes the article counts from each wiki&#39;s own API, and a monthly job takes the screenshots and uploads them to Cloudflare R2. The two are independent: separate files, separate pull requests, so they can&#39;t conflict. Until the first capture runs, a new wiki shows a monogram tile made from its initials — that&#39;s the intended look rather than a missing image, and it&#39;s also what you see if a screenshot ever fails to load.</p><p>Counts are rounded down and shown with a <code>+</code>, as in <code>1.1M+ articles</code>. That&#39;s why the page carries no &quot;last updated&quot; date: a rounded-down figure only gets truer as the wiki grows.</p><p>If a wiki&#39;s API can&#39;t be reached at all — a firewall that turns bots away, say, or a static site with no API — add <code>&quot;expectUnreachable&quot;: true</code> to its entry so the weekly job stops opening an issue about it every week. It only quiets the alert: the monthly job still captures a screenshot as usual.</p><div class="tip custom-block"><p class="custom-block-title">Maintainer note: what the showcase jobs need</p><p>Three workflows keep the showcase current, and each one needs something set up outside the repository.</p><p><strong>The refresh pull requests.</strong> Both jobs open their pull request as the Actions bot, so the docs CI run on it is created but held for approval — and that&#39;s the run that builds the Cloudflare preview the capture pull request asks you to look at, so the link goes nowhere until you hit <strong>Approve and run</strong> on the pull request. Adding a <code>SHOWCASE_PAT</code> repository secret for the jobs to use removes the click. It&#39;s optional; nothing else depends on it, and <code>release-please.yml</code> already uses a <code>WORKFLOW_TOKEN</code> personal access token for exactly the same reason — so check that one first rather than creating a second secret that does the same job.</p><p>Without a token, both jobs fall back to <code>GITHUB_TOKEN</code>, and no workflow here has ever opened a pull request that way. That path needs <strong>Allow GitHub Actions to create and approve pull requests</strong> turned on under <strong>Settings ▸ Actions ▸ General</strong>. If it&#39;s off, both jobs fail at the pull request step on their very first run.</p><p><strong>The screenshots.</strong> They live under the <code>shots/</code> prefix of <code>mwcitizen-media</code>, the Cloudflare R2 bucket that holds the docs site&#39;s media, published through the custom domain <code>media.mwcitizen.skin</code> bound to that bucket. Two repository secrets reach it: <code>CLOUDFLARE_ACCOUNT_ID</code> and <code>CLOUDFLARE_API_TOKEN</code>. The token needs R2 <strong>write and delete</strong> permission — write alone publishes fine but can&#39;t clean up, and the cleanup job then fails on every run. Both jobs install their own <code>wrangler</code> from <code>.github/actions/setup-wrangler</code>, which pins the exact version; that file is the only place to bump it.</p><p><strong>The cleanup.</strong> <code>showcase-gc.yml</code> runs on every push to <code>main</code> that touches <code>docs/data/showcase-shots.json</code> and permanently deletes the R2 objects that push dropped from the manifest. It runs after merge on purpose: while a capture pull request is open, <code>main</code> still serves the old screenshots and the preview serves the new ones, so both sets have to stay alive. Nothing lists the bucket, so the manifest diff is the only record of what&#39;s in it — a deleted screenshot can&#39;t be restored, only recaptured.</p></div><h2 id="contributors" tabindex="-1">Contributors <a class="header-anchor" href="#contributors" aria-label="Permalink to “Contributors”">​</a></h2><a href="https://github.com/StarCitizenTools/mediawiki-skins-citizen/graphs/contributors"><img src="https://contrib.rocks/image?repo=StarCitizenTools/mediawiki-skins-citizen" alt="Citizen contributors" title="Citizen contributors" width="812px"></a>`,33)])}var d=a(l,[[`render`,u]]);export{c as __pageData,d as default};